package model;
public class PrescriptionItem { private int itemId,prescriptionId; private String medicineName,dosage,frequency,duration; public int getItemId(){return itemId;} public void setItemId(int v){itemId=v;} public int getPrescriptionId(){return prescriptionId;} public void setPrescriptionId(int v){prescriptionId=v;} public String getMedicineName(){return medicineName;} public void setMedicineName(String v){medicineName=v;} public String getDosage(){return dosage;} public void setDosage(String v){dosage=v;} public String getFrequency(){return frequency;} public void setFrequency(String v){frequency=v;} public String getDuration(){return duration;} public void setDuration(String v){duration=v;} }
